package cl.skinspad.ticket.soporte;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.*;import com.fasterxml.jackson.databind.*;
import java.util.*;import java.util.concurrent.*;import java.math.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static cl.skinspad.ticket.soporte.EstadosSoporte.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:soporte;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop","escrow.job-initial-ms=3600000","soporte.job-inicial-ms=3600000"}) @AutoConfigureMockMvc
class SoporteIntegrationTest {
@Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired TicketRepository tickets;@Autowired TicketMensajeRepository mensajes;@Autowired SoporteEventoRepository eventos;@Autowired SoporteNotificacionRepository avisos;@Autowired SoporteAdjuntoRepository adjuntos;@Autowired SoporteCuotaRepository cuotas;
 @MockitoBean cl.skinspad.ticket.stats.StatsUserClient sessions;@MockitoBean SoporteCatalogoClient catalogo;@MockitoBean SoporteUsuarioClient usuarios;
 @MockitoBean PagoClient pagos;
 @BeforeEach void preparar(){adjuntos.deleteAll();mensajes.deleteAll();tickets.deleteAll();eventos.deleteAll();avisos.deleteAll();cuotas.deleteAll();
  when(sessions.validate(anyString())).thenAnswer(x->new cl.skinspad.ticket.stats.StatsUserClient.Identity(x.getArgument(0),((String)x.getArgument(0)).startsWith("admin")?"admin":"cliente",false));
  when(usuarios.obtener(anyString())).thenAnswer(x->new SoporteUsuarioClient.Usuario(x.getArgument(0),((String)x.getArgument(0)).startsWith("admin")?"admin":"cliente",false));
  when(catalogo.obtener(anyLong())).thenAnswer(x->skin(x.getArgument(0),100));
 }
 SoporteCatalogoClient.Publicacion skin(long id,int precio){return new SoporteCatalogoClient.Publicacion(id,"AK-47 | Redline","seller","rifle","ft",false,new BigDecimal("0.2"),"clasificado",BigDecimal.valueOf(precio),"ACTIVO",false);}
 JsonNode enviar(String ruta,String usuario,Object body,int status)throws Exception{var result=mvc.perform(post(ruta).header("Authorization","Bearer "+usuario).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsBytes(body))).andExpect(status().is(status)).andReturn();return result.getResponse().getContentAsString().isBlank()?mapper.createObjectNode():mapper.readTree(result.getResponse().getContentAsString());}
 Map<String,Object> nuevoTicket(){return Map.of("asunto","Consulta","categoria","PAGO","contenido","Necesito ayuda");}
 long ticket()throws Exception{return enviar("/api/tickets","buyer",nuevoTicket(),201).get("id").asLong();}
 @Test void ticketConversacionEstadoYNotificaciones()throws Exception{long id=ticket();enviar("/api/tickets/"+id+"/mensajes","admin",Map.of("contenido","Te ayudaremos"),200);var t=tickets.findById(id).orElseThrow();mvc.perform(patch("/api/admin/tickets/"+id+"/estado").header("Authorization","Bearer admin").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsBytes(Map.of("version",t.getVersion(),"estado","RESUELTO","motivo","Solucionado")))).andExpect(status().isOk());assertEquals(2,mensajes.findByTicket_IdOrderById(id).size());assertTrue(avisos.findTop50ByDestinatarioOrderByIdDesc("buyer").stream().anyMatch(a->a.getTexto().contains("respondió")));assertNotNull(tickets.findById(id).orElseThrow().getFechaCierre());enviar("/api/tickets/"+id+"/mensajes","buyer",Map.of("contenido","Nuevo mensaje"),409);}
 @Test void adjuntoRealPrivadoYMaliciosoRechazado()throws Exception{var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",out);var body=new HashMap<>(nuevoTicket());body.put("adjuntos",List.of(Map.of("nombre","captura.png","mime","image/png","base64",Base64.getEncoder().encodeToString(out.toByteArray()))));var t=enviar("/api/tickets","buyer",body,201);long id=t.get("adjuntos").get(0).get("id").asLong();mvc.perform(get("/api/tickets/adjuntos/"+id).header("Authorization","Bearer otro")).andExpect(status().isForbidden());mvc.perform(get("/api/tickets/adjuntos/"+id).header("Authorization","Bearer buyer")).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff"));body.put("adjuntos",List.of(Map.of("nombre","ataque.png","mime","image/png","base64",Base64.getEncoder().encodeToString("<html>ataque</html>".getBytes()))));enviar("/api/tickets","buyer",body,400);assertEquals(1,tickets.count());}
 @Test void cuotaConcurrenteNoExcedeCinco()throws Exception{
  for(int i=0;i<4;i++)ticket();var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var results=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)results.add(pool.submit(()->{gate.await();return mvc.perform(post("/api/tickets").header("Authorization","Bearer buyer").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsBytes(nuevoTicket()))).andReturn().getResponse().getStatus();}));gate.countDown();var codes=new ArrayList<Integer>();for(var f:results)codes.add(f.get(15,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(201,429),codes);assertEquals(5,tickets.count());}finally{pool.shutdownNow();}
 }
}
